\begin{tikzpicture}[font=\sffamily, >=Stealth, scale=1]
  % axes
  \draw[->] (0,0) -- (0,7.2);
  \draw[->] (0,0) -- (9,0);
  \node[right] at (0.1,6.9) {number of molecules};
  \node[below] at (8.4,-0.05) {kinetic energy};

  % T1 (solid): tall narrow peak at (1.8,6), starts at origin
  \draw[thick] (0,0) .. controls (0.9,0) and (1.1,6) .. (1.8,6)
               .. controls (2.5,6) and (3.2,0.8) .. (5.5,0.15)
               .. controls (6.5,0.02) and (7.5,0) .. (8.5,0);

  % T2 (dashed): higher temperature, lower and further right peak at (3.2,4), longer tail
  \draw[thick, dashed] (0,0) .. controls (1.4,0) and (2.0,4) .. (3.2,4)
               .. controls (4.3,4) and (5.2,1.2) .. (7.0,0.45)
               .. controls (7.8,0.3) and (8.2,0.05) .. (8.5,0);

  % activation energy
  \draw[dashed] (5.8,0) -- (5.8,6.5) node[above] {$E_{\mathrm{a}}$};

  % curve labels
  \node[above] at (1.8,6.05) {$T_{1}$};
  \node[above right] at (3.2,4.05) {$T_{2}$};

  % caption
  \node[below] at (4.5,-1.3) {\textbf{Fig. 5.1}};
\end{tikzpicture}

